def lattice_1d(power_num, power_den, N0=4000, tail_exp=None):
    """Upper bound of sum_{n in Z} (1+n^2)^{power_num} (2+n^2)^{-power_den}: exact partial sum over
    |n| <= N0 (interval arithmetic) plus the tail 2 sum_{n > N0} n^{-tail_exp} <= 2 (N0)^{1-tail_exp}/(tail_exp-1)
    (integral comparison; the summand is bounded by n^{-tail_exp} for n >= 1, see NOTE.md)."""
    s = Iv(Decimal(0))
    for n in range(-N0, N0 + 1):
        a = Iv.of(1 + n * n)
        b = Iv.of(2 + n * n)
        term = Iv(Decimal(1))
        for _ in range(power_num):
            term = term * a
        for _ in range(power_den):
            term = term / b
        s = s + term
    tail = 2 / ((tail_exp - 1) * Iv.of(N0 ** (tail_exp - 1)))     # 2 int_{N0}^inf x^{-tail_exp} dx
    return s + tail


